# a single tool definition passed to the Messages API
get_weather = {
    "name": "get_weather",
    "description": "Get the current weather for a city. "
                   "Use when the user asks about weather or temperature.",
    "input_schema": {
        "type": "object",
        "properties": {
            "city": {"type": "string", "description": "e.g. 'Paris'"},
            "unit": {"type": "string", "enum": ["c", "f"]},
        },
        "required": ["city"],
    },
}
tools = [get_weather]  # Claude reads this to decide when/how to call it

# 1. run the tool your code owns
output = get_weather_impl(city="Paris")   # 'Paris: 18C, light rain'

# 2. send the result back, linked by tool_use_id
messages.append({"role": "assistant", "content": resp.content})
messages.append({
    "role": "user",
    "content": [{
        "type": "tool_result",
        "tool_use_id": block.id,   # must match the tool_use id
        "content": output,
    }],
})
# next messages.create() call now 'sees' the weather

