# fake client so the example runs without network / keys
class Block:
    def __init__(self, **kw):
        self.__dict__.update(kw)

class FakeResp:
    def __init__(self):
        self.stop_reason = "tool_use"
        self.content = [Block(type="tool_use", id="toolu_01",
                              name="get_weather", input={"city": "Paris"})]

class FakeClient:
    class messages:
        @staticmethod
        def create(**kw):
            return FakeResp()

get_weather = {
    "name": "get_weather",
    "description": "Get current weather for a city.",
    "input_schema": {
        "type": "object",
        "properties": {"city": {"type": "string"}},
        "required": ["city"],
    },
}

resp = FakeClient.messages.create(
    model="claude-sonnet-4-5", max_tokens=1024,
    tools=[get_weather],
    messages=[{"role": "user", "content": "Weather in Paris?"}],
)

print("stop_reason:", resp.stop_reason)
for block in resp.content:
    if block.type == "tool_use":
        print("call:", block.name, block.input, "id=", block.id)

class Block:
    def __init__(self, **kw):
        self.__dict__.update(kw)

class FakeClient:
    def __init__(self):
        self.calls = 0
    class _M:
        def __init__(self, outer): self.outer = outer
        def create(self, **kw):
            self.outer.calls += 1
            if self.outer.calls == 1:
                r = Block(stop_reason="tool_use", content=[
                    Block(type="tool_use", id="toolu_01",
                          name="get_weather", input={"city": "Paris"})])
            else:
                r = Block(stop_reason="end_turn", content=[
                    Block(type="text", text="It's 18C and rainy in Paris.")])
            return r
    @property
    def messages(self): return FakeClient._M(self)

def get_weather_impl(city):
    return f"{city}: 18C, light rain"

IMPLS = {"get_weather": get_weather_impl}
tools = [{"name": "get_weather", "description": "weather",
          "input_schema": {"type": "object",
                           "properties": {"city": {"type": "string"}},
                           "required": ["city"]}}]

client = FakeClient()
messages = [{"role": "user", "content": "Weather in Paris?"}]
while True:
    resp = client.messages.create(model="claude-sonnet-4-5",
                                  max_tokens=1024, tools=tools,
                                  messages=messages)
    if resp.stop_reason != "tool_use":
        print("final:", resp.content[0].text)
        break
    messages.append({"role": "assistant", "content": resp.content})
    results = []
    for b in resp.content:
        if b.type == "tool_use":
            out = IMPLS[b.name](**b.input)          # act
            results.append({"type": "tool_result",
                            "tool_use_id": b.id, "content": out})
    messages.append({"role": "user", "content": results})  # observe
print("model calls:", client.calls)

