def run_tool_blocks(content, impls):
    results = []
    for b in content:
        if getattr(b, "type", None) != "tool_use":
            continue
        try:
            fn = impls[b.name]           # may KeyError on unknown tool
            out = fn(**b.input)          # run the tool our code owns
            results.append({
                "type": "tool_result",
                "tool_use_id": b.id,
                "content": str(out),
            })
        except Exception as e:
            # surface the failure to Claude instead of dropping the id
            results.append({
                "type": "tool_result",
                "tool_use_id": b.id,
                "content": f"error: {e}",
                "is_error": True,
            })
    return results

if __name__ == "__main__":
    class B:
        def __init__(self, **kw): self.__dict__.update(kw)
    blocks = [B(type="tool_use", id="t1", name="add", input={"a": 2, "b": 3}),
              B(type="tool_use", id="t2", name="boom", input={})]
    impls = {"add": lambda a, b: a + b, "boom": lambda: 1 / 0}
    for r in run_tool_blocks(blocks, impls):
        print(r["tool_use_id"], r["content"], r.get("is_error", False))
